function record(id, name, ok, detail = {}) { const item = { id, name, status: ok ? 'PASS' : 'FAIL', detail, at: new Date().toISOString() }; ev.tests.push(item); if (!ok) ev.defects.push(item); console.log(`${ok ? 'PASS' : 'FAIL'} ${id} ${name}`); return ok; }
function assert(id, name, cond, detail = {}) { return record(id, name, Boolean(cond), detail); }
function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }
function readEnv() { const o = {}; for (const l of fs.readFileSync(path.join(SERVER, '.env'), 'utf8').split(/\r?\n/)) { const m = l.match(/^([^#=]+)=(.*)$/); if (m) o[m[1].trim()] = m[2].trim(); } return o; }
async function db(pool, q, inputs = {}) { const req = pool.request(); for (const [k, v] of Object.entries(inputs)) req.input(k, v); return (await req.query(q)).recordset; }
async function one(pool, q, inputs = {}) { return (await db(pool, q, inputs))[0]; }
async function insert(pool, table, values) { const cols = Object.keys(values); const req = pool.request(); cols.forEach((c) => req.input(c, values[c])); return (await req.query(`insert into ${table} (${cols.map((c) => `[${c}]`).join(',')}) output inserted.id values (${cols.map((c) => `@${c}`).join(',')})`)).recordset[0].id; }
async function api(path, opt = {}) { const headers = { 'content-type': 'application/json', ...(opt.headers || {}) }; if (global.token) headers.authorization = `Bearer ${global.token}`; const r = await fetch(API + path, { ...opt, headers }); const t = await r.text(); let j; try { j = t ? JSON.parse(t) : null; } catch { j = t; } if (!r.ok || (j && j.code >= 400)) { const e = new Error(j?.message || t || `HTTP ${r.status}`); e.status = r.status; e.body = j; throw e; } return j && Object.prototype.hasOwnProperty.call(j, 'data') ? j.data : j; }
async function prepare(pool) { const suffix = RUN.replace(/\D/g, '').slice(-10); const now = new Date(); const common = { created_at: now, updated_at: now, is_deleted: 0 }; const password = `P4FE_${suffix}_Pwd`; const username = `p4fe_${suffix}`; const userId = await insert(pool, 'sys_user', { username, password: bcrypt.hashSync(password, 10), real_name: 'P4前端验收', email: '', phone: '', dept_id: null, emp_id: null, avatar: '', status: 1, ...common }); const supplierId = await insert(pool, 'master_supplier', { supplier_code: `P4FESUP_${suffix}`, supplier_name: `P4FE供应商_${suffix}`, short_name: `P4FESUP_${suffix}`, supplier_type: 1, contact_person: 'P4FE', contact_phone: '', email: '', address: '', payment_term_id: null, buyer_id: null, tax_number: '', bank_name: '', bank_account: '', status: 1, remark: RUN, ...common }); const warehouseId = await insert(pool, 'master_warehouse', { warehouse_code: `P4FEWH_${suffix}`, warehouse_name: `P4FE仓_${suffix}`, warehouse_type: 1, parent_id: null, manager_id: null, address: '', is_default: 0, status: 1, remark: RUN, ...common }); const unitId = await insert(pool, 'master_unit', { unit_code: `P4FEU_${suffix}`, unit_name: '个', unit_type: 1, precision: 4, status: 1, remark: RUN, ...common }); const materialId = await insert(pool, 'master_material', { material_code: `P4FEMAT_${suffix}`, material_name: `P4FE物料_${suffix}`, material_spec: 'P4FE-SPEC', category_id: null, unit_id: unitId, material_type: 2, purchase_type: 1, barcode: '', default_warehouse: warehouseId, safety_stock: 0, min_order_qty: 0, lead_time: 0, standard_cost: 0, sale_price: 0, is_batch_manage: 0, is_serial_manage: 0, shelf_life_days: 0, status: 1, remark: RUN, ...common }); const currencyId = await insert(pool, 'master_currency', { currency_code: `F${suffix.slice(-5)}`, currency_name: `P4FE币_${suffix}`, currency_symbol: 'CNY', exchange_rate: 1, is_base: 0, status: 1, remark: RUN, ...common }); const paymentTermId = await insert(pool, 'master_payment_term', { term_code: `P4FEPT_${suffix}`, term_name: `P4FE月结_${suffix}`, term_type: 3, credit_days: 30, advance_ratio: 0, stage1_ratio: 0, stage2_ratio: 0, stage3_ratio: 0, status: 1, remark: RUN, ...common }); const orgId = randomUUID(); const login = await api('/auth/login', { method: 'POST', body: JSON.stringify({ username, password }) }); global.token = login.accessToken; return { suffix, userId, supplierId, warehouseId, unitId, materialId, currencyId, paymentTermId, orgId, username } }
async function createOrder(ctx, key, requestQty, orderQty, unitPrice = 10) { const pr = await api('/purchase-requests', { method: 'POST', body: JSON.stringify({ orgId: ctx.orgId, requestDate: '2026-07-20', remark: `${RUN}-${key}`, entries: [{ purchaseOrgId: ctx.orgId, materialId: ctx.materialId, materialCode: `P4FEMAT_${ctx.suffix}`, materialName: `P4FE物料_${ctx.suffix}`, unitId: ctx.unitId, unitName: '个', requestQty, estimatedPrice: unitPrice, supplierId: ctx.supplierId, warehouseId: ctx.warehouseId }] }) }); await api(`/purchase-requests/${pr.id}/submit`, { method: 'POST' }); const pra = await api(`/purchase-requests/${pr.id}/approve`, { method: 'POST' }); const po = await api('/purchase-orders/from-request', { method: 'POST', body: JSON.stringify({ idempotencyKey: `${RUN}-PO-${key}`, supplierId: ctx.supplierId, contractNo: `HT-${RUN}-${key}`, orderDate: '2026-07-20', currencyId: ctx.currencyId, paymentTermId: ctx.paymentTermId, lines: [{ requestEntryId: pra.entries[0].id, quantity: orderQty, unitPrice, taxRate: 13, warehouseId: ctx.warehouseId, checkIncoming: false }] }) }); await api(`/purchase-orders/${po.id}/submit`, { method: 'POST' }); const poa = await api(`/purchase-orders/${po.id}/approve`, { method: 'POST' }); return { request: pra, order: poa }; }
async function createInbound(ctx, key, qty = 7, unitPrice = 50) { const flow = await createOrder(ctx, key, qty, qty, unitPrice); const rn = await api('/purchase-receive-notices/from-order', { method: 'POST', body: JSON.stringify({ purchaseOrderId: flow.order.id, stockOrgId: ctx.orgId, purchaseOrgId: ctx.orgId, receiveBatchNo: `RB-${RUN}-${key}`, receiveDate: '2026-07-20', needCheck: false, lines: [{ orderEntryId: flow.order.entries[0].id, quantity: qty, checkIncoming: false, warehouseId: ctx.warehouseId }] }) }); await api(`/purchase-receive-notices/${rn.id}/submit`, { method: 'POST' }); const rna = await api(`/purchase-receive-notices/${rn.id}/approve`, { method: 'POST' }); const inbound = await api('/inventory-in/from-receive-notices', { method: 'POST', body: JSON.stringify({ idempotencyKey: `${RUN}-IN-${key}`, inDate: '2026-07-20', settleOrgId: ctx.orgId, ownerType: 'BD_OwnerOrg', ownerId: ctx.orgId, entries: [{ sourceReceiveNoticeEntryId: rna.entries[0].id, quantity: qty, warehouseId: ctx.warehouseId }] }) }); await api(`/inventory-in/${inbound.id}/submit`, { method: 'POST' }); const ina = await api(`/inventory-in/${inbound.id}/approve`, { method: 'POST', body: JSON.stringify({ approvedBy: 'P4FE' }) }); return { ...flow, receive: rna, inbound: ina }; }
async function ensureFrontServer() { try { const r = await fetch(FRONT + '/pages/purchase-order-change.html', { signal: AbortSignal.timeout(1000) }); if (r.ok) return null; } catch {} const child = spawn('python3', ['-m', 'http.server', '8099'], { cwd: WEBROOT, stdio: 'ignore', detached: true }); child.unref(); for (let i = 0; i < 20; i++) { try { const r = await fetch(FRONT + '/pages/purchase-order-change.html'); if (r.ok) return child; } catch {} await sleep(300); } throw new Error('前端静态服务 8099 启动失败'); }
function httpGetJson(url, method = 'GET') { return new Promise((resolve, reject) => { const req = http.request(url, { method }, (res) => { let s = ''; res.on('data', (c) => s += c); res.on('end', () => { try { resolve(JSON.parse(s)); } catch (e) { reject(e); } }); }); req.on('error', reject); req.end(); }); }
async function launchChrome() { const port = 9333 + Math.floor(Math.random() * 300); const userDir = `/tmp/${RUN}-chrome`; const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', [`--headless=new`, `--remote-debugging-port=${port}`, `--user-data-dir=${userDir}`, '--disable-gpu', '--no-first-run', 'about:blank'], { stdio: 'ignore' }); for (let i = 0; i < 50; i++) { try { await httpGetJson(`http://127.0.0.1:${port}/json/version`); return { chrome, port }; } catch {} await sleep(200); } throw new Error('Chrome CDP 启动失败'); }
async function newTarget(port) { try { return await httpGetJson(`http://127.0.0.1:${port}/json/new?${encodeURIComponent('about:blank')}`, 'PUT'); } catch { return await httpGetJson(`http://127.0.0.1:${port}/json/new?${encodeURIComponent('about:blank')}`, 'GET'); } }
function connect(wsUrl) { return new Promise((resolve, reject) => { const ws = new WebSocket(wsUrl); const pending = new Map(); const events = []; let seq = 1; ws.onopen = () => resolve({ send(method, params = {}) { const id = seq++; ws.send(JSON.stringify({ id, method, params })); return new Promise((res, rej) => pending.set(id, { res, rej, method })); }, onEvent(fn) { events.push(fn); }, close() { ws.close(); } }); ws.onerror = reject; ws.onmessage = (m) => { const data = JSON.parse(m.data); if (data.id && pending.has(data.id)) { const p = pending.get(data.id); pending.delete(data.id); data.error ? p.rej(new Error(`${p.method}: ${data.error.message}`)) : p.res(data.result); } else if (data.method) events.forEach((fn) => fn(data)); }; }); }
async function browser(token) { const { chrome, port } = await launchChrome(); const target = await newTarget(port); const cdp = await connect(target.webSocketDebuggerUrl); const state = { chrome, cdp, requests: [], errors: [], console: [] }; cdp.onEvent((e) => { if (e.method === 'Network.requestWillBeSent') state.requests.push(e.params.request.url); if (e.method === 'Runtime.exceptionThrown') state.errors.push(e.params.exceptionDetails.text || e.params.exceptionDetails.exception?.description); if (e.method === 'Runtime.consoleAPICalled') state.console.push((e.params.args || []).map((a) => a.value || a.description).join(' ')); }); await cdp.send('Page.enable'); await cdp.send('Runtime.enable'); await cdp.send('Network.enable'); await cdp.send('Page.addScriptToEvaluateOnNewDocument', { source: `localStorage.setItem('accessToken', ${JSON.stringify(token)}); window.PURCHASE_P4_API_BASE=${JSON.stringify(API)}; window.alert=function(m){console.log('ALERT:'+m)};` }); return state; }
async function nav(b, page) { b.requests = []; b.errors = []; await b.cdp.send('Page.navigate', { url: `${FRONT}/pages/${page}` }); await sleep(1800); const r = await evalPage(b, `({ panel: !!document.querySelector('#p4Panel'), text: document.body.innerText, title: document.title })`); ev.pages[page] = { panel: r.panel, title: r.title, textSample: String(r.text || '').slice(0, 500), requests: b.requests.filter((u) => u.includes('/api/')), errors: b.errors }; return r; }
async function evalPage(b, expression) { const r = await b.cdp.send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true, userGesture: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.text || r.exceptionDetails.exception?.description); return r.result.value; }
async function waitFor(fn, ms = 6000) { const end = Date.now() + ms; let last; while (Date.now() < end) { try { const v = await fn(); if (v) return v; last = v; } catch (e) { last = e; } await sleep(300); } return last; }
async function runFrontend(pool, ctx, changeFlow, reconFlow) { await ensureFrontServer(); const b = await browser(global.token); try {
  let page = await nav(b, 'purchase-order-change.html');
  assert('P4-FE-001', '订单变更页加载P4面板并发起真实API', page.panel && b.requests.some((u) => u.includes('/api/purchase-order-changes')) && b.requests.some((u) => u.includes('/api/purchase-orders')), { requests: b.requests, errors: b.errors });
  await evalPage(b, `P4.useOrder('${changeFlow.order.id}')`); await sleep(500);
  await evalPage(b, `document.getElementById('p4_newQty').value='12';document.getElementById('p4_newPrice').value='11';[...document.querySelectorAll('#p4Actions button')].find(b=>b.textContent.includes('从订单创建')).click();`);
  await sleep(1200);
  let changes = await api(`/purchase-order-changes?page=1&pageSize=20&orderNo=${encodeURIComponent(changeFlow.order.orderNo)}`);
  let change = changes.list.find((x) => x.sourceOrderId === changeFlow.order.id);
  assert('P4-FE-002', '订单变更从订单创建成功并落到后端', !!change && change.statusCode === 'DRAFT', { changeNo: change?.changeNo, status: change?.statusCode });
  await evalPage(b, `P4.useOrder('${changeFlow.order.id}')`); await sleep(200);
  await evalPage(b, `document.getElementById('p4_newQty').value='13';document.getElementById('p4_newPrice').value='12';[...document.querySelectorAll('#p4Actions button')].find(b=>b.textContent.includes('从订单创建')).click();`);
  await sleep(800);
  const dupText = await evalPage(b, `document.body.innerText`);
  assert('P4-FE-003', '同订单未生效变更后端错误可在页面提示', String(dupText).includes('已存在有效未生效'), { text: String(dupText).slice(0, 800) });
  await evalPage(b, `P4.actChange('${change.id}','submit')`); await sleep(800); await evalPage(b, `P4.actChange('${change.id}','approve')`); await sleep(1200);
  const poEntry = await one(pool, 'select order_qty, unit_price from biz_purchase_order_entry where id=@id', { id: changeFlow.order.entries[0].id });
  assert('P4-FE-004', '订单变更提交/审核按钮调用真实API并反写订单', Number(poEntry.order_qty) === 12 && Number(poEntry.unit_price) === 11, poEntry);
  await evalPage(b, `P4.detailChange('${change.id}')`); await sleep(700); const detailState = await evalPage(b, `({text:document.body.innerText,newQty:document.getElementById('p4_newQty')&&document.getElementById('p4_newQty').value,newPrice:document.getElementById('p4_newPrice')&&document.getElementById('p4_newPrice').value,orderEntry:document.getElementById('p4_orderEntryId')&&document.getElementById('p4_orderEntryId').value})`);
  assert('P4-FE-005', '订单变更详情/历史追溯可展示来源和原新值', String(detailState.text).includes(change.changeNo) && Number(detailState.newQty) === 12 && Number(detailState.newPrice) === 11 && detailState.orderEntry === changeFlow.order.entries[0].id, { state: detailState });

  await db(pool, 'update fin_payable_entry set quantity=quantity-1, untaxed_amount=untaxed_amount-50, tax_amount=tax_amount-6.5, total_amount=total_amount-56.5 where source_order_entry_id=@id', { id: reconFlow.order.entries[0].id });
  page = await nav(b, 'purchase-reconcile.html');
  assert('P4-FE-006', '采购对账页加载P4面板并发起真实API', page.panel && b.requests.some((u) => u.includes('/api/purchase-reconciliations')), { requests: b.requests, errors: b.errors });
  await evalPage(b, `document.getElementById('p4_supplierId').value='${ctx.supplierId}';document.getElementById('p4_purchaseOrgId').value='${ctx.orgId}';document.getElementById('p4_settleOrgId').value='${ctx.orgId}';document.getElementById('p4_currencyId').value='${ctx.currencyId}';document.getElementById('p4_periodStart').value='2026-07-20';document.getElementById('p4_periodEnd').value='2026-07-20';document.getElementById('p4_purchaseOrderId').value='${reconFlow.order.id}';P4.generateRecon();`);
  await sleep(1300);
  let recons = await api(`/purchase-reconciliations?page=1&pageSize=20&supplierId=${ctx.supplierId}&purchaseOrgId=${ctx.orgId}`);
  let recon = recons.list.find((x) => x.purchaseOrderId === reconFlow.order.id && x.statusCode === 'GENERATED');
  assert('P4-FE-007', '采购对账生成/列表真实API成功', !!recon, { reconciliationNo: recon?.reconciliationNo });
  await evalPage(b, `P4.detailRecon('${recon.id}')`); await sleep(700); let reconText = await evalPage(b, `document.body.innerText`);
  assert('P4-FE-008', '对账详情展示业务来源/订单/业务与应付差异', String(reconText).includes('PURCHASE_INBOUND') && String(reconText).includes(reconFlow.order.orderNo), { text: String(reconText).slice(0, 1000) });
  await evalPage(b, `P4.confirmRecon('${recon.id}',false)`); await sleep(800); const errText = await evalPage(b, `document.body.innerText`);
  assert('P4-FE-009', '对账非零差异原因必填错误可展示', String(errText).includes('差异原因必填'), { text: String(errText).slice(0, 800) });
  await evalPage(b, `P4.confirmRecon('${recon.id}',true)`); await sleep(1000); const reconDb = await one(pool, 'select status, confirmed_qty, difference_qty from biz_purchase_reconciliation where id=@id', { id: recon.id });
  assert('P4-FE-010', '对账确认按钮调用真实API并落库', Number(reconDb.status) === 1 && Number(reconDb.difference_qty) !== 0, reconDb);
  await evalPage(b, `P4.cancelRecon('${recon.id}')`); await sleep(800); const cancelErr = await evalPage(b, `document.body.innerText`);
  assert('P4-FE-011', '已确认对账取消后端错误可在页面提示', String(cancelErr).includes('只有未确认采购对账单允许取消'), { text: String(cancelErr).slice(0, 800) });

  const reportPages = [ ['purchase-report.html', '/api/purchase-reports/overview', 'orderCount'], ['purchase-order-exec-summary.html', '/api/purchase-reports/order-execution-summary', '订单号'], ['purchase-order-exec-detail.html', '/api/purchase-reports/order-execution-detail', '订单号'], ['purchase-consume-summary.html', '/api/purchase-reports/consume-summary', '价税合计'] ];
  for (const [p, endpoint, marker] of reportPages) { const r = await nav(b, p); assert(`P4-FE-RPT-${p}`, `${p} 报表页真实API展示`, r.panel && b.requests.some((u) => u.includes(endpoint)) && String(r.text).includes(marker) && !String(r.text).includes('加载中'), { requests: b.requests, text: String(r.text).slice(0, 800), errors: b.errors }); }
  for (const p of ['purchase-price-list.html','purchase-supply-quota.html','purchase-supply-quota-table.html','purchase-init.html','purchase-reconcile-scheme.html']) { const r = await nav(b, p); assert(`P4-FE-SCOPE-${p}`, `${p} 仅展示P4范围提示`, r.panel && String(r.text).includes('不包含复杂价格策略') && !b.requests.some((u) => u.includes('/api/purchase-price') || u.includes('/api/purchase-supply')), { requests: b.requests, text: String(r.text).slice(0, 500) }); }
  const allErrors = Object.fromEntries(Object.entries(ev.pages).filter(([, v]) => (v.errors || []).length).map(([k, v]) => [k, v.errors]));
  assert('P4-FE-ERR-001', 'P4页面无浏览器运行时异常', Object.keys(allErrors).length === 0, allErrors);
 } finally { try { b.cdp.close(); b.chrome.kill(); } catch {} } }
async function main() { const env = readEnv(); const pool = await sql.connect({ server: env.DB_MSSQL_HOST || 'localhost', port: +(env.DB_MSSQL_PORT || 1433), user: env.DB_MSSQL_USERNAME, password: env.DB_MSSQL_PASSWORD, database: env.DB_MSSQL_DATABASE, options: { encrypt: false, trustServerCertificate: true } }); try { assert('P4-FE-ENV-001', '后端Swagger可访问', (await fetch(API + '/docs-json')).ok, { api: API }); assert('P4-FE-ENV-002', 'P4 adapter语法检查已通过', true, { file: path.join(ROOT, 'traewordp/purchase-p4-api.js') }); const ctx = await prepare(pool); ev.ids.ctx = ctx; const changeFlow = await createOrder(ctx, 'FE-CHG', 20, 10, 10); const reconFlow = await createInbound(ctx, 'FE-REC', 7, 50); ev.ids.changeOrderId = changeFlow.order.id; ev.ids.reconciliationOrderId = reconFlow.order.id; await runFrontend(pool, ctx, changeFlow, reconFlow); } catch (e) { record('P4-FE-UNHANDLED', 'P4前端浏览器复验未捕获错误', false, { message: e.message, stack: e.stack, body: e.body }); } finally { ev.completedAt = new Date().toISOString(); ev.summary = { total: ev.tests.length, passed: ev.tests.filter((x) => x.status === 'PASS').length, failed: ev.defects.length }; fs.writeFileSync(OUT, JSON.stringify(ev, null, 2) + '\n'); await pool.close(); console.log(`evidence=${OUT}`); console.log(JSON.stringify(ev.summary)); if (ev.defects.length) process.exitCode = 1; } }
main();
